effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }

// LAYER -> SCREEN. The wave is generated from layer coordinates and every read
// comes back through the layer transform, so it deforms the layer itself.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float vnoise(vec2 p){
vec2 i = floor(p);
vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), f.x),
           mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), f.x), f.y);
}

// One period of each waveform, all returning -1..1 so they can be summed.
float waveEval(float ph){
if (waveShape <= 0) return sin(ph);
if (waveShape <= 1) return 0.6366198 * asin(clamp(sin(ph), -1.0, 1.0));
if (waveShape <= 2) return sign(sin(ph));
if (waveShape <= 3) return 2.0 * fract(ph / 6.2831853) - 1.0;
if (waveShape <= 4) return vnoise(vec2(ph * 0.35, 0.0)) * 2.0 - 1.0;
if (waveShape <= 5) return sin(ph) * exp(-abs(ph) * 0.20);
return sin(ph);
}

vec2 edgeFix(vec2 lp){
if (edgeMode <= 0) return clamp(lp, 0.0, 1.0);
if (edgeMode <= 1){
vec2 m = mod(lp, vec2(2.0, 2.0));
return abs(m - vec2(1.0, 1.0)) * -1.0 + vec2(1.0);
}
return fract(lp);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  c0  = centre - vec2(0.5);
c0.x *= asp;
vec2  q   = lp - vec2(0.5);
q.x *= asp;
q -= c0;

// ---- direction and phase coordinate ------------------------------------
// These are deliberately separate: a radial wave displaces outward but its
// phase runs on the radius, an angular wave displaces tangentially but its
// phase runs on the angle. Coupling them would make half the combinations
// impossible to express.
float coord;
vec2  dir;
if (waveAxis <= 0){
coord = lp.y;
dir   = vec2(1.0, 0.0);
} else if (waveAxis <= 1){
coord = lp.x;
dir   = vec2(0.0, 1.0);
} else if (waveAxis <= 2){
coord = length(q);
float ql = max(length(q), 1.0e-4);
dir = q / ql;
} else if (waveAxis <= 3){
coord = atan(q.y, q.x) / 6.2831853;
float ql = max(length(q), 1.0e-4);
dir = vec2(-q.y, q.x) / ql;
} else {
float ra = radians(angle);
vec2  ax = vec2(cos(ra), sin(ra));
coord = dot(q, ax);
dir   = vec2(-ax.y, ax.x);
}

float ph = (coord * wavelength + phase / 360.0 + acTime * speed) * 6.2831853;

// ---- harmonic stack -----------------------------------------------------
float acc  = 0.0;
float wsum = 0.0;
float amp  = 1.0;
float k    = 1.0;
for (int i = 0; i < 4; i++){
if (float(i) >= float(harmonics)) break;
acc  += amp * waveEval(ph * k);
wsum += amp;
amp  *= max(harmonicFall, 0.05);
k    += 1.0;
}
float d = acc / max(wsum, 1.0e-4);

// ---- cross wave ---------------------------------------------------------
if (crossWave > 0.001){
float coord2 = (waveAxis <= 0) ? lp.x : lp.y;
float ph2 = (coord2 * wavelength * 1.7 - acTime * speed * 1.3) * 6.2831853;
d += waveEval(ph2) * crossWave * 0.6;
}

// ---- turbulence / taper / flag -----------------------------------------
if (turbulence > 0.001){
d += (vnoise(lp * 6.0 + vec2(acTime * 0.20, acTime * 0.13)) - 0.5) * turbulence * 0.60;
}
if (waveShape >= 6){
// Flag: anchored at the left edge, so amplitude grows across the layer.
d *= clamp(lp.x, 0.0, 1.0);
}
d *= 1.0 - taper * smoothstep(0.0, 0.5, abs(lp.x - 0.5) * 2.0);
d *= amplitude;

vec2 dpos = lp + dir * d;
vec4 got  = texture2DCv(inputImg.texture, clamp(lpToScreen(edgeFix(dpos)), 0.0, 1.0));
float ga  = max(got.a, 1.0e-4);
vec3 gc   = got.rgb / ga;

vec3  col = mix(sc, gc, mixAmt);
float oA  = got.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
